        UnityPrint("nan");
    }
    else if (__builtin_isinf_sign(number))
    {
        UnityPrint("inf");
    }
    else
    {
        UNITY_INT32 n_int = 0, n;
        int exponent = 0;
        int decimals, digits;
        char buf[16] = {0};
        if (number < 1.0f)
        {
            UNITY_DOUBLE factor = 1.0f;
            while (number < (UNITY_DOUBLE)max_scaled / 1e10f)
            {
                number *= 1e10f;
                exponent -= 10;
            }
            while (number * factor < (UNITY_DOUBLE)min_scaled)
            {
                factor *= 10.0f;
                exponent--;
            }
            number *= factor;
        }
        else if (number > (UNITY_DOUBLE)max_scaled)
        {
            UNITY_DOUBLE divisor = 1.0f;
            while (number > (UNITY_DOUBLE)min_scaled * 1e10f)
            {
                number /= 1e10f;
                exponent += 10;
            }
            while (number / divisor > (UNITY_DOUBLE)max_scaled)
            {
                divisor *= 10.0f;
                exponent++;
            }
            number /= divisor;
        }
        else
        {
            UNITY_DOUBLE factor = 1.0f;
            n_int = (UNITY_INT32)number;
            number -= (UNITY_DOUBLE)n_int;
            while (n_int < min_scaled)
            {
                n_int *= 10;
                factor *= 10.0f;
                exponent--;
            }
            number *= factor;
        }
        n = ((UNITY_INT32)(number + number) + 1) / 2;
        if ((n & 1) && (((UNITY_DOUBLE)n - number) == 0.5f))
            n--;
        n += n_int;
        if (n >= max_scaled)
        {
            n = min_scaled;
            exponent++;
        }
        decimals = ((exponent <= 0) && (exponent >= -(sig_digits + 3))) ? (-exponent) : (sig_digits - 1);
        exponent += decimals;
        while ((decimals > 0) && ((n % 10) == 0))
        {
            n /= 10;
            decimals--;
        }
        digits = 0;
        while ((n != 0) || (digits < (decimals + 1)))
        {
            buf[digits++] = (char)('0' + n % 10);
            n /= 10;
        }
        while (digits > 0)
        {
            if (digits == decimals)
            {
                (void)putchar('.');
            }
            (void)putchar(buf[--digits]);
        }
        if (exponent != 0)
        {
            (void)putchar('e');
            if (exponent < 0)
            {
                (void)putchar('-');
                exponent = -exponent;
            }
            else
            {
                (void)putchar('+');
            }
            digits = 0;
            while ((exponent != 0) || (digits < 2))
            {
                buf[digits++] = (char)('0' + exponent % 10);
                exponent /= 10;
            }
            while (digits > 0)
            {
                (void)putchar(buf[--digits]);
            }
